/* Blog listing and articles (/blog/...), generated by scripts/blog_build.py.
 *
 * The title, description, canonical and Article schema are already in the
 * HTML. They are passed back to PR.seo.apply so the site-wide defaults from
 * the SEO Manager don't replace them, while the shared tags (Organization,
 * verification, analytics) still come from there.
 */
(function () {
  'use strict';
  var PR = window.PR;

  function content(selector) {
    var el = document.querySelector(selector);
    return el ? (el.getAttribute('content') || el.getAttribute('href') || '') : '';
  }

  document.addEventListener('DOMContentLoaded', function () {
    PR.mountLayout('blog', false);
    var canonical = content('link[rel="canonical"]');
    var isArticle = content('meta[property="og:type"]') === 'article';
    var crumbs = [{ name: 'Home', url: '/' }, { name: 'Blog', url: '/blog/' }];
    if (isArticle) {
      var h1 = document.querySelector('h1');
      crumbs.push({ name: h1 ? h1.textContent : document.title, url: canonical });
    }
    PR.seo.apply({
      key: 'blog',
      title: document.title,
      description: content('meta[name="description"]'),
      canonical: canonical,
      image: content('meta[property="og:image"]'),
      type: isArticle ? 'article' : 'website',
      breadcrumbs: crumbs
    });
  });
})();
